var _markdown = "\n\n`CCarCtrl.h`\n\n交通密度、随机车、脚本造车、AI 挂路网。和 [CPopulation](/docs/plugins/entities/population) / [CPathFind](/docs/plugins/entities/pathfind) 配套。\n\n## 密度与计数 [#密度与计数]\n\n<Api name=\"CarDensityMultiplier / MaxNumberOfCarsInUse\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static float& CarDensityMultiplier;\n      static unsigned int& MaxNumberOfCarsInUse;\n      static int& NumRandomCars;\n      static int& NumMissionCars;\n      static int& NumParkedCars;\n      static int& NumPermanentVehicles;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // CCarCtrl::CarDensityMultiplier = 0.0f; // 少车\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 应急与警察车 [#应急与警察车]\n\n<Api name=\"NumLawEnforcerCars / bAllowEmergencyServicesToBeCreated\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static unsigned int& NumLawEnforcerCars;\n      static unsigned int& NumAmbulancesOnDuty;\n      static unsigned int& NumFireTrucksOnDuty;\n      static bool& bAllowEmergencyServicesToBeCreated;\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      CCarCtrl::bAllowEmergencyServicesToBeCreated = false;\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 脚本造车 [#脚本造车]\n\n<Api name=\"CreateCarForScript / SetCoordsOfScriptCar\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static CVehicle* CreateCarForScript(int modelid, CVector posn, unsigned char MissionCleanUpFlag);\n      static void SetCoordsOfScriptCar(CVehicle* pVehicle, float x, float y, float z, unsigned char arg5, unsigned char arg6);\n      static CVehicle* GetNewVehicleDependingOnCarModel(int modelID, unsigned char createdBy);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 模型已加载：\n      // CVehicle* v = CCarCtrl::CreateCarForScript(model, pos, 1);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 随机生成 [#随机生成]\n\n<Api name=\"GenerateRandomCars / GenerateEmergencyServicesCar\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void GenerateRandomCars();\n      static void GenerateOneRandomCar();\n      static void GenerateEmergencyServicesCar();\n      static bool GenerateOneEmergencyServicesCar(unsigned int modelID, CVector posn);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 游戏主循环会调；ASI 一般只改密度/开关\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 挂路网 [#挂路网]\n\n<Api name=\"JoinCarWithRoadSystem / JoinCarWithRoadSystemGotoCoors\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void JoinCarWithRoadSystem(CVehicle* pVehicle);\n      static bool JoinCarWithRoadSystemGotoCoors(CVehicle* pVehicle, CVector const& posn, bool unused, bool bIsBoat);\n      static void JoinCarWithRoadAccordingToMission(CVehicle* pVehicle);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // CCarCtrl::JoinCarWithRoadSystem(veh);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 移除与兴趣车 [#移除与兴趣车]\n\n<Api name=\"PossiblyRemoveVehicle / RegisterVehicleOfInterest\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void PossiblyRemoveVehicle(CVehicle* pVehicle);\n      static void RemoveDistantCars();\n      static void RemoveCarsIfThePoolGetsFull();\n      static void RegisterVehicleOfInterest(CVehicle* pVehicle);\n      static void RemoveFromInterestingVehicleList(CVehicle* pVehicle);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 池满时游戏会清远车；任务车要保护好标志\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 上下乘客 [#上下乘客]\n\n<Api name=\"SetUpDriverAndPassengersForVehicle\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static void SetUpDriverAndPassengersForVehicle(CVehicle* pVehicle, int arg2, int arg3, bool arg4, bool arg5, int passengersNum);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      // 随机交通填充驾驶员/乘客\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n";
